          "id": "bchu5",
          "nodes": [
            {
              "type": "TEXT",
              "id": "",
              "nodes": [],
              "textData": {
                "text": "Nuts and seeds: Nuts and seeds such as almonds, cashews, and sesame seeds are often used to add texture and flavor to dishes.",
                "decorations": []
              }
            }
          ],
          "paragraphData": {
            "textStyle": {
              "textAlignment": "AUTO"
            },
            "indentation": 0
          }
